// Build an event object. retryCount is only attached when willRetry is true.
function makeEvent(type, willRetry) {
  const e = { type: type, payload: {} };
  if (willRetry) {
    e.retryCount = 0;
  }
  return e;
}
function shapeSig(o) { return Object.keys(o).join(','); }

