function normalise(raw) {
  const r = {};
  // copy whatever keys arrived, in the order they arrived
  for (const k of Object.keys(raw)) {
    r[k] = raw[k];
  }
  // fill in optional fields if missing
  if (r.score === undefined) r.score = 0;
  if (r.label === undefined) r.label = null;
  // a derived field
  if (raw.kind === 'premium') {
    r.weight = 2;
  }
  return r;
}
